"""Node.js · referencia completa (etapa 6)."""
from .tabla import filas

E6 = filas(r"""
fs/promises ¦ fs/promises ¦ versión con promesas del módulo de archivos ¦ leer y escribir archivos con async y await ¦ import { readFile, writeFile } from "node:fs/promises";⏎await writeFile("nota.txt", "hola");⏎console.log(await readFile("nota.txt", "utf8")); ¦ escribe y lee un archivo con await ¦ usar las funciones Sync dentro de un servidor
Recorrer carpetas ¦ readdir ¦ funciones para listar carpetas y saber qué es cada cosa ¦ buscar todos los archivos .md de un proyecto ¦ import { readdir } from "node:fs/promises";⏎const todo = await readdir(".", { recursive: true, withFileTypes: true });⏎console.log(todo.filter((f) => f.isFile() && f.name.endsWith(".md")).length); ¦ cuenta los archivos Markdown ¦ recorrer node_modules sin querer
Vigilar archivos ¦ fs.watch ¦ función que avisa cuando cambia un archivo ¦ recargar la configuración al editarla ¦ import { watch } from "node:fs";⏎watch("config.json", () => console.log("Configuración cambiada")); ¦ avisa al editar el archivo ¦ recibir avisos duplicados y no agruparlos
readline ¦ readline ¦ módulo para leer la entrada del teclado o archivos línea por línea ¦ hacer preguntas en un programa de terminal ¦ import readline from "node:readline/promises";⏎const rl = readline.createInterface({ input: process.stdin, output: process.stdout });⏎const n = await rl.question("¿Tu nombre? ");⏎console.log(`Hola ${n}`); rl.close(); ¦ pregunta el nombre y saluda ¦ olvidar cerrar la interfaz
util.promisify y util.parseArgs ¦ parseArgs ¦ utilidades para convertir callbacks en promesas y leer argumentos ¦ leer --puerto desde la terminal ¦ import { parseArgs } from "node:util";⏎const { values } = parseArgs({ options: { puerto: { type: "string", default: "3000" } } });⏎console.log(values.puerto); ¦ lee la opción --puerto ¦ leer process.argv a mano
Eventos de process ¦ process.on ¦ eventos para reaccionar a errores y al cierre del programa ¦ cerrar conexiones antes de salir ¦ process.on("SIGINT", () => { console.log("Cerrando..."); process.exit(0); });⏎process.on("unhandledRejection", (e) => console.error("Promesa sin catch:", e)); ¦ maneja Ctrl + C y promesas sin catch ¦ seguir funcionando después de un error grave sin reiniciar
AsyncLocalStorage ¦ AsyncLocalStorage ¦ forma de guardar datos de una petición a lo largo del código asíncrono ¦ registrar el id de cada petición en todos los logs ¦ import { AsyncLocalStorage } from "node:async_hooks";⏎const ctx = new AsyncLocalStorage();⏎ctx.run({ id: 7 }, async () => { await null; console.log("petición", ctx.getStore().id); }); ¦ recuerda el id en código asíncrono ¦ pasar el id manualmente por todas las funciones
Timers con promesas ¦ timers/promises ¦ versión con promesas de setTimeout ¦ esperar sin callbacks ¦ import { setTimeout as esperar } from "node:timers/promises";⏎await esperar(100);⏎console.log("pasaron 100 ms"); ¦ espera 100 ms con await ¦ envolver setTimeout en promesas a mano
Módulo zlib ¦ zlib ¦ módulo para comprimir y descomprimir ¦ comprimir respuestas o archivos ¦ import { gzipSync, gunzipSync } from "node:zlib";⏎const c = gzipSync("hola ".repeat(100));⏎console.log(c.length, gunzipSync(c).toString().length); ¦ comprime y descomprime un texto ¦ comprimir archivos que ya están comprimidos
pipeline de streams ¦ pipeline ¦ función que conecta streams y maneja los errores ¦ comprimir un archivo grande sin cargarlo en memoria ¦ import { pipeline } from "node:stream/promises";⏎import { createReadStream, createWriteStream } from "node:fs";⏎import { createGzip } from "node:zlib";⏎// await pipeline(createReadStream("log.txt"), createGzip(), createWriteStream("log.txt.gz"));⏎console.log("pipeline"); ¦ comprime el archivo por partes ¦ usar pipe sin manejar los errores
SQLite integrado ¦ node:sqlite ¦ base de datos SQLite incluida en Node ¦ guardar datos sin instalar nada ¦ import { DatabaseSync } from "node:sqlite";⏎const db = new DatabaseSync(":memory:");⏎db.exec("CREATE TABLE t (n TEXT)");⏎db.prepare("INSERT INTO t VALUES (?)").run("Ana");⏎console.log(db.prepare("SELECT n FROM t").all()); ¦ crea, inserta y consulta en SQLite ¦ usarlo en versiones viejas de Node
Permisos de Node ¦ --permission ¦ modo que limita qué puede hacer un programa ¦ ejecutar código ajeno con menos riesgo ¦ // node --permission --allow-fs-read=./datos app.js⏎console.log("permisos"); ¦ permite leer solo la carpeta datos ¦ dar todos los permisos a scripts que no conoces
Ejecutar TypeScript en Node ¦ --experimental-strip-types ¦ ejecutar archivos .ts directamente en versiones nuevas de Node ¦ probar TypeScript sin compilar ¦ // node app.ts   (Node 23.6 o más reciente)⏎const n: number = 5;⏎console.log(n); ¦ ejecuta TypeScript quitando los tipos ¦ esperar que Node revise los tipos
package.json exports ¦ exports ¦ campo que define qué archivos de tu paquete se pueden importar ¦ publicar una librería ordenada ¦ // "exports": { ".": "./dist/index.js", "./utilidades": "./dist/util.js" }⏎console.log("exports"); ¦ define los puntos de entrada del paquete ¦ dejar que importen archivos internos
Imports internos con # ¦ "imports" ¦ alias internos definidos en package.json ¦ evitar rutas como ../../../ ¦ // "imports": { "#db": "./src/db.js" }⏎// import db from "#db";⏎console.log("imports"); ¦ importa la base de datos con un alias ¦ olvidar el signo # en el nombre
pnpm y yarn ¦ pnpm ¦ gestores de paquetes alternativos a npm ¦ instalar dependencias más rápido y ahorrando espacio ¦ // corepack enable⏎// pnpm install⏎// pnpm add express⏎console.log("pnpm"); ¦ instala dependencias con pnpm ¦ mezclar archivos de bloqueo de varios gestores
Bun y Deno ¦ bun ¦ entornos de JavaScript alternativos a Node ¦ probar herramientas más rápidas ¦ // bun run index.ts⏎// deno run --allow-net servidor.ts⏎console.log("Bun y Deno"); ¦ ejecuta TypeScript con Bun y Deno ¦ asumir que todos los paquetes de npm funcionan igual
PM2 ¦ pm2 ¦ gestor de procesos para mantener tu app encendida ¦ reiniciar la app si se cae ¦ // npm i -g pm2⏎// pm2 start app.js --name api -i max⏎// pm2 logs api⏎console.log("pm2"); ¦ arranca la app en todos los núcleos ¦ usar nodemon en producción
Hono ¦ Hono ¦ framework web pequeño que funciona en Node, Bun y la nube ¦ crear una API muy rápida ¦ // import { Hono } from "hono";⏎// const app = new Hono();⏎// app.get("/", (c) => c.json({ ok: true }));⏎console.log("Hono"); ¦ crea una ruta que responde JSON ¦ elegir framework sin revisar dónde se va a desplegar
Drizzle ORM ¦ drizzle ¦ ORM ligero y con tipos para bases SQL ¦ consultar la base con autocompletado ¦ // const usuarios = sqliteTable("usuarios", { id: integer("id").primaryKey(), nombre: text("nombre") });⏎// await db.select().from(usuarios).where(eq(usuarios.id, 1));⏎console.log("Drizzle"); ¦ define una tabla y la consulta ¦ olvidar crear las migraciones
""")

